<?php
namespace App\Models;use App\Models\Concerns\InvalidatesIndustries;use Illuminate\Database\Eloquent\Builder;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\{BelongsTo,BelongsToMany,HasMany};
class Industry extends Model{use HasFactory,InvalidatesIndustries;protected $fillable=['industry_category_id','title','slug','eyebrow','short_description','overview','challenge_summary','outcome_summary','icon','featured_image_path','featured_image_alt','hero_style','template','status','is_featured','display_order','published_at','scheduled_for','archived_at','primary_cta_label','primary_cta_url','secondary_cta_label','secondary_cta_url','meta_title','meta_description','canonical_url','og_title','og_description','og_image_path','robots_index','robots_follow','created_by','updated_by'];protected function casts():array{return ['is_featured'=>'boolean','robots_index'=>'boolean','robots_follow'=>'boolean','published_at'=>'datetime','scheduled_for'=>'datetime','archived_at'=>'datetime'];}public function category():BelongsTo{return $this->belongsTo(IndustryCategory::class,'industry_category_id');}public function challenges():HasMany{return $this->hasMany(IndustryChallenge::class)->orderBy('display_order');}public function outcomes():HasMany{return $this->hasMany(IndustryOutcome::class)->orderBy('display_order');}public function needs():HasMany{return $this->hasMany(IndustryNeed::class)->orderBy('display_order');}public function useCases():HasMany{return $this->hasMany(IndustryUseCase::class)->orderBy('display_order');}public function relatedSolutions():BelongsToMany{return $this->belongsToMany(Solution::class,'industry_solution_relations')->withPivot('display_order')->orderByPivot('display_order');}public function relatedProducts():BelongsToMany{return $this->belongsToMany(Product::class,'industry_product_relations')->withPivot('display_order')->orderByPivot('display_order');}public function relatedPages():BelongsToMany{return $this->belongsToMany(Page::class,'industry_page_relations')->withPivot('display_order')->orderByPivot('display_order');}public function navigationItems():HasMany{return $this->hasMany(NavigationItem::class);}public function homepageItems():HasMany{return $this->hasMany(HomepageItem::class);}public function scopePubliclyVisible(Builder $q):Builder{return $q->whereNull('archived_at')->whereNotNull('short_description')->where(fn(Builder $q)=>$q->where(fn(Builder $x)=>$x->where('status','published')->whereNotNull('published_at')->where('published_at','<=',now()))->orWhere(fn(Builder $x)=>$x->where('status','scheduled')->whereNotNull('scheduled_for')->where('scheduled_for','<=',now())));}public function isPubliclyVisible():bool{return $this->archived_at===null&&trim((string)$this->short_description)!==''&&(($this->status==='published'&&$this->published_at?->lte(now()))||($this->status==='scheduled'&&$this->scheduled_for?->lte(now())));}}
